using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    private static ReportingConfiguration ReportingConfiguration =>
        s_reportingConfiguration ??= CreateReportingConfiguration();

    private ScenarioRun? _scenarioRun;

    [TestInitialize]
    public async Task Initialize()
    {
        _scenarioRun =
            await ReportingConfiguration.CreateScenarioRunAsync(
                TestContext.TestRunResultsDirectory!,
                TestContext.FullyQualifiedTestClassName!,
                TestContext.TestName!);
    }

    [TestCleanup]
    public async Task Cleanup()
    {
        if (_scenarioRun is not null)
        {
            await _scenarioRun.DisposeAsync();
        }
    }

    public TestContext TestContext { get; set; } = default!;

    [TestMethod]
    public async Task Chat_responds_relevantly()
    {
        IChatClient chatClient = _scenarioRun!.GetChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await _scenarioRun.EvaluateAsync(messages);

        Assert.IsTrue(
            response.Text!.Contains("Paris", StringComparison.OrdinalIgnoreCase),
            "Response should mention Paris.");
    }

    [TestMethod]
    public async Task Chat_follows_system_prompt()
    {
        IChatClient chatClient = _scenarioRun!.GetChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that answers in exactly one sentence."),
            new(ChatRole.User, "Explain what .NET Aspire is.")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await _scenarioRun.EvaluateAsync(messages);

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(response.Text),
            "Response should not be empty.");
    }

    [TestMethod]
    public async Task Chat_handles_multi_turn_conversation()
    {
        IChatClient chatClient = _scenarioRun!.GetChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice.")
        };

        ChatResponse response1 = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response1.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        ChatResponse response2 = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response2.Messages);

        await _scenarioRun.EvaluateAsync(messages);

        Assert.IsTrue(
            response2.Text!.Contains("Alice", StringComparison.OrdinalIgnoreCase),
            "Response should recall the user's name.");
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT environment variable.");
        var modelId = Environment.GetEnvironmentVariable("AZURE_OPENAI_CHAT_DEPLOYMENT") ?? "gpt-4o-mini";

        IEvaluator[] evaluators =
        [
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        ];

        return new ReportingConfiguration(
            chatClientConfiguration: DiskBasedReportingConfiguration.CreateChatClientConfiguration(
                (builder, _) =>
                {
                    var credential = new Azure.Identity.DefaultAzureCredential();
                    builder.Use(new Azure.AI.Inference.ChatCompletionsClient(
                        new Uri(endpoint), credential).AsChatClient(modelId));
                }),
            evaluators: evaluators,
            reportStorageConfiguration: DiskBasedReportingConfiguration.CreateFileBasedReportStorageConfiguration());
    }
}

